/**
 * Manages the {@link JointComponent}s of an application. Reach it through `app.systems.joint`;
 * components are created with {@link Entity#addComponent}, never by calling the system directly.
 *
 * @category Physics
 * @alpha
 */
export class JointComponentSystem extends ComponentSystem {
    /**
     * Joints waiting for their rigid bodies to enter the simulation.
     *
     * @type {Set<JointComponent>}
     * @private
     */
    private _pending;
    /**
     * Joints with an active constraint and a finite break impulse.
     *
     * @type {Set<JointComponent>}
     * @private
     */
    private _breakable;
    id: string;
    ComponentType: typeof JointComponent;
    initializeComponentData(component: any, data: any, properties: any): void;
    cloneComponent(entity: any, clone: any): import("../component.js").Component;
    /**
     * @param {Entity} entity - The entity the component is being removed from.
     * @param {JointComponent} component - The component being removed.
     * @private
     */
    private onBeforeRemove;
    /**
     * @param {number} dt - The frame delta time in seconds.
     * @private
     */
    private onUpdate;
    /**
     * @param {number} dt - The frame delta time in seconds.
     * @private
     */
    private onPostUpdate;
}
import { ComponentSystem } from '../system.js';
import { JointComponent } from './component.js';
